style.css:
@-moz-document domain("investopedia.com") {
/* ====================================================================
     Palette (GitHub-dark family; Investopedia blue adapted for dark)
       base bg        #14181d
       elevated       #1c2128
       header/footer  #0d1117
       border subtle  #262c33 / component #2d333b
       text primary   #e6edf3   body #c4cdd6   muted #8b949e
       link/accent    #5fb0e6 (hover #9bd4ff)  brand-blue origin rgb(7,88,167)
     ==================================================================== */

  :root {
    color-scheme: dark !important;
    /* Re-point Investopedia's own legacy design tokens so anything that
       still references them lands on the dark palette. */
    --lt-color-white: #14181d !important;
    --lt-color-gray-100: #1c2128 !important;
    --lt-color-gray-200: #1c2128 !important;
    --lt-color-gray-300: #262c33 !important;
    --lt-color-gray-400: #2d333b !important;
    --lt-color-gray-500: #c4cdd6 !important;
    --lt-color-gray-600: #c4cdd6 !important;
    --lt-color-gray-700: #e6edf3 !important;
    --lt-color-gray-800: #14181d !important;
    --color-background: #14181d !important;
    --color-text-primary: #e6edf3 !important;
  }

  /* ====================================================================
     Base surfaces
     ==================================================================== */
  html, body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Mantle layout wrappers / generic component containers -> transparent so
     the dark body shows through; opaque dark is re-established below on every
     card, header, search and floating surface. */
  #main, .loc.main, .loc.content, .article-content, .article-body,
  .comp.article, .comp.article--sc, .mntl-article, .mntl-block,
  .mntl-sc-page, .structured-content, .loc.article-content,
  .l-container, .article__content, .three-column__content,
  .right-rail, .article__header, .loc.title, .loc.byline,
  .mntl-leaderboard-header, .mntl-leaderboard-spacer {
    background-color: transparent !important;
  }

  /* ====================================================================
     Typography
     ==================================================================== */
  h1, h2, h3, h4, h5, h6,
  .article-heading, .mntl-text-block, .heading__title,
  .mntl-sc-block-heading, .finance-sc-block-heading,
  .comp.article-heading, .loc.title,
  .mntl-sc-block-subheading, .article-subheading,
  .breadcrumbs-nav__title, .breadcrumb__link,
  .card__title, .card__content, .card__title-text {
    color: #e6edf3 !important;
  }
  p, li, span, td, th, dd, dt, figcaption, blockquote,
  .mntl-sc-block-html, .article-body p, .comp.article-body,
  .mntl-attribution__item, .byline, .mntl-bypass-attribution,
  .loc.byline, .mntl-attribution__item-name,
  .article-subheading--type-byline {
    color: #c4cdd6 !important;
  }
  .text-utility-100, .figure-caption, .mntl-figure-caption,
  .article-info, .mntl-timestamp, .recirc-text, .updated-date,
  .mntl-attribution__item-date, .meta, small {
    color: #8b949e !important;
  }
  /* Card author byline ("By <name>" on home / category / related-rail cards).
     Live default is a near-black rgba(0,0,0,.65) set via -webkit-text-fill-color,
     so it vanishes on the dark card — lift it to a legible muted grey and clear
     the fill-color override so it actually takes. */
  .byline--simple, .byline--simple__author,
  .card__byline, .mntl-card__byline,
  .card__byline a, .mntl-card__byline a,
  .card__content .byline--simple,
  .card__content .byline--simple__author {
    color: #8b949e !important;
    -webkit-text-fill-color: #8b949e !important;
  }

  /* ====================================================================
     Links / brand accent (Investopedia blue rgb(7,88,167) -> dark-friendly)
     ==================================================================== */
  a, a:link, a:visited,
  .mntl-sc-block-html a, .article-body a, .card a,
  .related-articles__link, .mntl-toc__list-item-link,
  .terms-bar__item a, .miso-list__item-body, .breadcrumb__link {
    color: #5fb0e6 !important;
  }
  a:hover, .mntl-sc-block-html a:hover, .article-body a:hover,
  .card a:hover, .related-articles__link:hover {
    color: #9bd4ff !important;
  }
  /* Cards: titles/links over dark card surface */
  .mntl-universal-card .card__title, .mntl-universal-card .card__content,
  .card .card__title, .card .card__content, .card__title-text,
  .home-hero-card .card__title, .home-hero-card .card__content {
    color: #e6edf3 !important;
  }

  /* ====================================================================
     Header / global nav  (Mantle .mntl-header)
     ==================================================================== */
  header.mntl-header, .comp.header.mntl-header,
  .mntl-header__menu-top, .mntl-header__bottom,
  .mntl-header-nav, .mntl-header-nav__list,
  .header-nav, .header-nav__category-list,
  .mntl-fullscreen-nav, .mntl-fullscreen-nav__list,
  .mntl-nav-menu, .mntl-sub-nav, .nav__menu {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
    color: #e6edf3 !important;
  }
  /* Article/search header variant: the nav list + its items keep a white bg
     on a more specific live selector — raise specificity so the dark wins. */
  ul.mntl-header-nav__list, ul.mntl-header-nav__list > li,
  li.mntl-header-nav__list-item,
  header.mntl-header .mntl-header-nav,
  header.mntl-header .mntl-header-nav__list,
  header.mntl-header .mntl-header-nav__list-item,
  header.mntl-header .mntl-header__menu-top,
  header.mntl-header .mntl-header__bottom,
  header.mntl-header nav, header.mntl-header .mntl-nav-menu {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }
  .mntl-header a, .mntl-header-nav a, .mntl-header__logo + * a,
  .header-nav__list-item a, .mntl-fullscreen-nav a,
  .mntl-header-nav__list-item, .mntl-text-link,
  ul.mntl-header-nav__list a, li.mntl-header-nav__list-item a {
    color: #e6edf3 !important;
  }
  .mntl-header a:hover, .mntl-header-nav a:hover,
  .header-nav__list-item a:hover { color: #5fb0e6 !important; }
  /* Header logo / svg glyphs */
  .mntl-header__logo svg, .mntl-header svg,
  .mntl-fullscreen-nav__toggle svg { color: #e6edf3 !important; fill: #e6edf3 !important; }
  /* Header wordmark: the logo is an inline SVG <use href="#icon-logo">; the
     #icon-logo <symbol> (in a hidden sprite, NOT inside svg.icon-logo) carries
     near-black/navy paths (fill="#201d1e" / fill="#323a56") that disappear on
     the dark header. Recoloring the symbol's source paths recolors the rendered
     <use> instance. Light the dark fills; keep the brand orange dot. */
  #icon-logo path { fill: #e6edf3 !important; }
  #icon-logo circle,
  #icon-logo path[fill="#f64e00"],
  #icon-logo circle[fill="#f64e00"] { fill: #f64e00 !important; }
  /* Newsletter-dialog wordmark uses a separate sprite (#icon-logo-finance) whose
     source paths are pure black — invisible on the now-dark dialog. Light them,
     keep the brand orange dot. */
  .newsletter__logo svg, svg.icon-logo-finance, svg.icon-logo-finance path,
  #icon-logo-finance path { fill: #e6edf3 !important; }
  #icon-logo-finance path[fill="#f64e00"],
  #icon-logo-finance circle[fill="#f64e00"],
  svg.icon-logo-finance path[fill="#f64e00"] { fill: #f64e00 !important; }

  /* Dropdown / fullscreen-nav panels must be opaque */
  .mntl-fullscreen-nav__menu, .mntl-fullscreen-nav__container,
  .mntl-header-nav__category, .header-nav__sublist,
  .mntl-dropdown, .mntl-flyout, .nav-menu__dropdown {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ====================================================================
     Search  (.miso-search-box + .mntl-search-form)
     ==================================================================== */
  .miso-search-box, .miso-search-box__input-group,
  div.miso-search-box__input-group,
  .miso-search-box .miso-search-box__input-group,
  .mntl-search-form, .mntl-search-form--hero, .search-bar,
  .mntl-search-form__form, form.mntl-search-form__form,
  .mntl-search-form__input-group, .mntl-search-form .input-group,
  .mntl-utility-nav__search, .mntl-hero-search,
  .search-results__hero-search {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Header search "Search" field label (renders blue text on the now-white
     form) -> muted grey; the magnifier/close icon glyphs -> light. */
  .mntl-search-form__label, .mntl-search-form__label.text-utility-300-prominent { color: #8b949e !important; }
  .mntl-search-form__button svg, .mntl-search-form__close-button svg,
  .mntl-search-form__button use, .mntl-search-form__close-button use {
    color: #e6edf3 !important; fill: #e6edf3 !important;
  }
  /* Search hero band (light-blue rgb(197,220,255) by default) + its heading */
  section.mntl-hero-search, .mntl-hero-search.search-results__hero-search,
  section.search-results__hero-search.mntl-hero-search,
  section.search-results__hero-search,
  body section.mntl-hero-search,
  .mntl-hero-search__container {
    background: #14181d !important;
    background-color: #14181d !important;
  }
  .mntl-hero-search__title, .mntl-hero-search__subtitle,
  .mntl-hero-search .link__wrapper { color: #e6edf3 !important; }
  .miso-search-box__input, .mntl-search-form__input,
  input[type="search"], input[type="text"], textarea, select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .miso-search-box__input::placeholder,
  .mntl-search-form__input::placeholder,
  input::placeholder, textarea::placeholder { color: #8b949e !important; }
  /* Search autocomplete / results dropdown -> opaque */
  .miso-list, .miso-search-box__results, .mntl-search-form__suggestions,
  .search-suggestions, .miso-results {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .miso-list__item, .miso-list__item-body,
  a.miso-list__item-body, .miso-list a.miso-list__item-body,
  .miso-search-box__results .miso-list__item-body {
    background-color: transparent !important;
  }
  a.miso-list__item-body, .miso-list a.miso-list__item-body,
  a.miso-list__item-body * { color: #c4cdd6 !important; }
  .miso-list__item:hover, a.miso-list__item-body:hover { background-color: #2d333b !important; }
  .miso-search-box__input-group .miso-search-box__button,
  .mntl-search-form__button { background-color: transparent !important; }

  /* ====================================================================
     Cards / lists / carousels  (universal-card, home-hero, carousel)
     ==================================================================== */
  .mntl-universal-card, .mntl-card-list-items, .card,
  .mntl-carousel__card, .carousel-card, .mntl-block.carousel-card,
  .home-hero-card, .home-hero-primary__item, .home-hero-secondary__item,
  .card--hero, .prm-block__best-rate-item, .advisors__item,
  .sim-promo__child-container, .eat-trust, .mntl-five-post__background,
  .mntl-card, .comp.card, .recirc-list__item, .related-articles__item,
  .mntl-document-card {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  .mntl-universal-card:hover, .card:hover, .home-hero-card:hover,
  .mntl-carousel__card:hover { background-color: #21262d !important; }

  /* Key-terms / carousel card body: a ::after scroll-fade "more below" gradient
     fades the clamped definition text to pure WHITE (rgba(255,255,255,0) → #fff)
     — doubly audit-blind (a pseudo-element AND a bg-IMAGE gradient) — so it paints
     a glaring white strip across the bottom of every dark card. Remap the fade to
     the card's own dark surface so the affordance survives without the white. */
  .carousel-card__body::after, .comp.carousel-card__body::after,
  [id^="carousel-card__body"]::after {
    background-image: linear-gradient(rgba(28, 33, 40, 0) 75%, #1c2128) !important;
  }

  /* Decorative card "fold" square: a 16px ::after the live site paints pure
     white — invisible on the white card, but a glaring white speck on the dark
     card body (home-hero card titles + card summaries). Merge it back into the
     card surface so it disappears the way it does on the light original. */
  .card__title-text::after, .card__summary::after,
  .home-hero-card .card__title-text::after,
  .mntl-universal-card .card__title-text::after,
  .card .card__title-text::after, .card .card__summary::after {
    background-color: #1c2128 !important;
  }

  /* "Our Mission" / EAT-trust block carries a light grey background-IMAGE
     gradient (rgba(225,226,230,.5)) painted over its surface — invisible to a
     bg-color audit but it washes the lower half of the panel grey. Kill the
     image so the dark card surface stays uniform. */
  .eat-trust, .comp.eat-trust, [id^="eat-trust"] {
    background-image: none !important;
  }

  /* Card / figure image CONTAINERS (white bg behind/around images) */
  .card__media, .universal-image, .universal-image__image,
  .card__img, .figure-image, .img-placeholder, .loading-image,
  .mntl-image, .lazy-image, .placeholder, .mntl-sc-block-image,
  .finance-sc-block-image, .figure-landscape, .figure-portrait,
  .img-wrapper, .image__placeholder {
    background-color: #1c2128 !important;
  }

  /* ====================================================================
     Table of contents (sticky)  + table of contents nav
     ==================================================================== */
  .sticky-toc-wrapper, .mntl-toc, .mntl-toc__menu, .comp.mntl-toc,
  .toc, .article-toc, .mntl-sc-block-keyterms,
  .mntl-sc-block-keyterms__nav, .key-terms {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .mntl-toc__list-item-link, .toc__link, .mntl-toc a { color: #c4cdd6 !important; }
  .mntl-toc__list-item-link:hover, .mntl-toc__list-item--active a,
  .mntl-toc__list-item-link.is-active { color: #5fb0e6 !important; }
  /* Key-terms pill nav buttons */
  .mntl-sc-block-keyterms__nav-item, .mntl-button {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .mntl-sc-block-keyterms__nav-item:hover,
  .mntl-sc-block-keyterms__nav-item.is-active { background-color: #2d333b !important; color: #e6edf3 !important; }

  /* ====================================================================
     Callouts  (theme-whatyouneedtoknow / theme-note / theme-important)
     elevated surface + a refined blue accent border, text kept readable
     ==================================================================== */
  .finance-sc-block-callout, .mntl-sc-block-callout,
  .mntl-sc-block-universal-callout, .comp.theme-note,
  .comp.theme-important, .comp.theme-whatyouneedtoknow {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  .finance-sc-block-callout.theme-whatyouneedtoknow,
  .mntl-sc-block-universal-callout.theme-whatyouneedtoknow {
    border-left: 4px solid #5fb0e6 !important;
  }
  .finance-sc-block-callout.theme-important,
  .mntl-sc-block-universal-callout.theme-important {
    border-left: 4px solid #e0823d !important;
  }
  .finance-sc-block-callout.theme-note,
  .mntl-sc-block-universal-callout.theme-note {
    border-left: 4px solid #3fb950 !important;
  }
  .finance-sc-block-callout *, .mntl-sc-block-universal-callout * {
    background-color: transparent !important;
  }
  .finance-sc-block-callout .mntl-sc-block-heading,
  .finance-sc-block-callout strong,
  .mntl-sc-block-universal-callout .mntl-sc-block-heading { color: #e6edf3 !important; }

  /* Question & answer / definition blocks */
  .finance-sc-block-questionandanswer,
  .mntl-sc-block-questionandanswer {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .mntl-sc-block-questionandanswer__question,
  .finance-sc-block-questionandanswer .mntl-sc-block-questionandanswer__question {
    color: #e6edf3 !important;
  }

  /* ====================================================================
     "Part of the Series" journey accordion (learning-path module on term /
     guide articles). The container is a bordered card; its section headers
     ("How Dividends Work", "Introduction to Dividend Investing") and the
     "CURRENT ARTICLE" label render near-black (color AND
     -webkit-text-fill-color rgba(0,0,0,.95)) -> invisible on the dark surface.
     Elevate the card, light the headers, mute the label.
     ==================================================================== */
  .journey-accordion, .comp.journey-accordion, [id^="journey-accordion"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .journey-accordion__item, .journey-accordion__root,
  .journey-accordion__item-header, .journey-accordion__item-content,
  .journey-accordion__item.is-active > .journey-accordion__item-header {
    background-color: transparent !important;
  }
  .journey-accordion__item-header,
  .journey-accordion__item.is-active > .journey-accordion__item-header,
  .journey-accordion__item > .journey-accordion__item-header {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  .journey-accordion__item--current-article,
  .journey-accordion__current-article,
  .journey-accordion__sublist-item--current-article,
  .journey-accordion__series-eyebrow, .journey-accordion__eyebrow {
    color: #8b949e !important;
    -webkit-text-fill-color: #8b949e !important;
  }

  /* ====================================================================
     Category / hub "Explore" filter bar  (mntl-taxonomysc-* family)
     A category-only class set: chip pills render white with near-black
     labels, the active "All" pill bright white, and the list track a
     light grey. Recolor the bar, the pills, and the active state.
     ==================================================================== */
  .mntl-taxonomysc, .mntl-taxonomysc-article-list-group {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .mntl-taxonomysc-child-links__list, .mntl-taxonomysc-child-node,
  a.mntl-taxonomysc-child-node, a.mntl-taxonomysc-child-links__list,
  .mntl-taxonomysc-child-node__more-button,
  button.mntl-taxonomysc-child-node__more-button.mntl-button {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* Active / selected chip ("All" carries .is-active) — dark surface,
     bright label so it reads as selected without the white pill. */
  .mntl-taxonomysc-child-node.is-active,
  .mntl-taxonomysc-child-node__view-all.is-active,
  a.mntl-taxonomysc-child-node.is-active {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  .mntl-taxonomysc-child-node:hover { background-color: #2d333b !important; color: #e6edf3 !important; }
  /* List track (group ::after light-grey rgb(239,239,239)) + chip tracks */
  .mntl-taxonomysc-article-list-group::after,
  .mntl-taxonomysc-child-node::after { background-color: #2d333b !important; }
  /* "More" flyout panel: the absolutely-positioned dropdown container itself is
     transparent — only its pills are opaque — so the article grid behind it
     bleeds through the gaps between pills. Give the panel a solid dark surface. */
  .mntl-taxonomysc-child-node__dropdown,
  .comp.mntl-taxonomysc-child-node__dropdown {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* "Investopedia Answers" (askmiso) GenAI query widget */
  .askmiso-ask-query, .askmiso-ask-query-base,
  .askmiso-ask-query__ask-container, .askmiso-ask-query-heading,
  .askmiso-ask-query-secondary, .askmiso-ask-query-secondary-heading {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  /* askmiso decorative ::after halo paints a large white disc on dark */
  .askmiso-ask-query::after, .askmiso-ask-query-base::after,
  .askmiso-ask-query-secondary::after { background: #1c2128 !important; }
  .askmiso-ask-query__heading, .askmiso-ask-query-heading { color: #e6edf3 !important; }
  .askmiso-ask-query__subheading { color: #8b949e !important; }
  .askmiso-ask-query__search, .askmiso-ask-query input, .askmiso-ask-query textarea {
    background-color: #14181d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .askmiso-ask-query input::placeholder, .askmiso-ask-query textarea::placeholder { color: #8b949e !important; }
  .askmiso-ask-query__submit, .askmiso-ask-query button {
    background-color: #2563a8 !important; color: #ffffff !important; border-color: #2563a8 !important;
  }

  /* ====================================================================
     Homepage "Premium rates" module  (.prm-block family)
     The whole module wrapper is painted by a LIGHT lavender background-IMAGE
     (homepage-prm-block-background.jpg) — invisible to a bg-color audit — so it
     renders as a light panel behind the (already dark) rate cards. The
     "OUR TOP PICKS FOR JUNE:" sub-block + its bullet links and the "Earn X% APY"
     titles are near-black (color AND -webkit-text-fill-color rgba(0,0,0,.95)) →
     unreadable. Kill the light image, darken the wrapper, and lift every line.
     ==================================================================== */
  .prm-block, .comp.prm-block, .prm-block--wrapper,
  .prm-block__top-picks, .prm-block__best-rate, .prm-block__best-rates {
    background-image: none !important;
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }
  /* "OUR TOP PICKS FOR JUNE:" heading (default royal-blue rgb(44,64,208)) */
  .prm-block__top-picks--subtitle, .prm-block__top-picks--title,
  .prm-block__top-picks .mntl-text-block {
    color: #c4cdd6 !important;
  }
  /* "Earn 5.00% APY While You Can" rate-card titles (near-black by default) */
  .prm-block__best-rate--title,
  .prm-block__best-rate-item .prm-block__best-rate--title {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* "Compare Rates →" links + the OUR-TOP-PICKS bullet links
     (bullets are near-black via -webkit-text-fill-color) -> accent blue */
  .prm-block__best-rate--link,
  .prm-block__top-picks a, .prm-block__top-picks--list a,
  .prm-block__top-picks li a, .prm-block a {
    color: #5fb0e6 !important;
    -webkit-text-fill-color: #5fb0e6 !important;
  }
  .prm-block__top-picks a:hover, .prm-block a:hover {
    color: #9bd4ff !important;
    -webkit-text-fill-color: #9bd4ff !important;
  }

  /* Homepage "Investopedia for Advisors" band carries a light lavender raster
     background-IMAGE (homepage-advisor-background) painted on the wrapper whose
     own bg-color is transparent — audit-blind (a url(), not a gradient) — so the
     whole band renders light and hides its (light) title + subtitle. Kill the
     image and darken the wrapper; the item cards are already dark. */
  .advisors, .comp.advisors, [id^="advisors_"] {
    background-image: none !important;
    background-color: #14181d !important;
  }

  /* ====================================================================
     Tables  (rate tables, data tables) — keep finance green/red intact
     ==================================================================== */
  table, .mntl-table, .comp.mntl-sc-block-table,
  .rate-table, .mid-bankingtable, .mid-ad-table-group,
  .mntl-sc-block-table__table,
  .mntl-sc-block-universal-table__table,
  .mntl-sc-block-universal-table__table-wrapper,
  .mntl-sc-block-universal-table__table-wrapper--no-scroll,
  .mntl-sc-block-universal-table__table-wrapper--scroll {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  /* The universal-table wrapper also carries a white horizontal scroll-shadow
     background-IMAGE gradient (linear-gradient(to right, #fff, ...)) that paints
     over the dark bg-color — audit-blind, and it bleeds a white strip at the
     wrapper's left edge wherever a child (e.g. the transparent figcaption
     footnote) doesn't cover it. Kill the image so the dark surface stays clean. */
  .mntl-sc-block-universal-table__table-wrapper,
  .mntl-sc-block-universal-table__table-wrapper--no-scroll,
  .mntl-sc-block-universal-table__table-wrapper--scroll {
    background-image: none !important;
  }
  th, .mntl-table thead, .mntl-table th, table thead th {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  td, table td, .mntl-table td {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }
  tr:nth-child(even) td { background-color: #181d23 !important; }

  /* ====================================================================
     Breadcrumbs / related-terms bar / dictionary
     ==================================================================== */
  .breadcrumbs-nav, .breadcrumb, .comp.breadcrumbs-nav,
  .mntl-breadcrumbs, .mntl-breadcrumbs__list, .mntl-breadcrumbs__item,
  .terms-bar, .terms-bar__list, .related-terms,
  .dictionary-top24-list, .tod, .tod--dictionary {
    background-color: transparent !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }
  /* Breadcrumb link pills render white with blue text by default */
  a.mntl-breadcrumbs__link, a.mntl-text-link.mntl-breadcrumbs__link,
  .mntl-breadcrumbs__item a.mntl-breadcrumbs__link {
    background-color: transparent !important;
    color: #5fb0e6 !important;
  }
  .terms-bar__item, .terms-bar__item a { color: #c4cdd6 !important; }
  .terms-bar__item.is-active, .terms-bar__item:hover {
    background-color: #2d333b !important; color: #e6edf3 !important;
  }

  /* ====================================================================
     Author / attribution / trust block
     ==================================================================== */
  .mntl-attribution, .article-info, .mntl-bypass-attribution,
  .mntl-attribution__details, .author-bio, .mntl-author {
    background-color: transparent !important; color: #c4cdd6 !important;
  }
  .mntl-attribution__item-name:not(.mntl-author-tooltip__name) { color: #e6edf3 !important; }

  /* ====================================================================
     Footer  (already dark navy rgb(50,58,86) -> align to palette)
     ==================================================================== */
  footer.mntl-footer, .comp.footer.mntl-footer, .mntl-footer,
  .mntl-footer__top, .mntl-footer__bottom, .footer {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }
  .mntl-footer a, .footer a, .mntl-footer__menu-link { color: #c4cdd6 !important; }
  .mntl-footer a:hover, .footer a:hover { color: #5fb0e6 !important; }
  .mntl-footer__logo svg, .mntl-footer svg { fill: #c4cdd6 !important; color: #c4cdd6 !important; }

  /* ====================================================================
     Universal nav strip (Dotdash family bar at bottom)
     ==================================================================== */
  .mntl-dotdash-universal-nav, .mntl-carbon-dotdash-universal-nav,
  div.comp.mntl-dotdash-universal-nav,
  div.mntl-dotdash-universal-nav,
  .comp.mntl-dotdash-universal-nav {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }
  .mntl-dotdash-universal-nav a,
  .mntl-dotdash-universal-nav__text,
  .mntl-dotdash-universal-nav span,
  .mntl-dotdash-universal-nav__title,
  div.comp.mntl-dotdash-universal-nav a,
  div.comp.mntl-dotdash-universal-nav .mntl-dotdash-universal-nav__text { color: #c4cdd6 !important; }

  /* Skip-to-content link (off-screen until keyboard-focused) */
  .mntl-skip-to-content, .mntl-skip-to-content:focus,
  .mntl-skip-to-content .link__wrapper {
    background-color: #1c2128 !important; color: #e6edf3 !important;
  }
  .mntl-skip-to-content .link__wrapper { color: #e6edf3 !important; }

  /* ====================================================================
     Ad slots / leaderboards — darken empty/loading slots (don't theme iframe)
     ==================================================================== */
  .mm-ads-leaderboard-header, .leaderboard, .mm-ads-leaderboard-flex-1,
  .mntl-leaderboard, .mntl-universal-card-list--extendable-ad-slot,
  .leaderboard--fixed-lazy, .mm-ads-leaderboard-fixed-lazy,
  [id^="div-gpt-ad-"], [id*="google_ads_iframe"], ins.adsbygoogle,
  .sc-ad-container, .partner-block,
  div.mm-ads-leaderboard-header, div.leaderboard--fixed-lazy,
  div.leaderboard--fixed-lazy.mm-ads-leaderboard-header,
  div.leaderboard--fixed-lazy.mm-ads-leaderboard-flex-1,
  div.mntl-universal-card-list--extendable-ad-slot,
  [class*="mm-ads-leaderboard"], [class*="leaderboard--fixed"],
  [class*="extendable-ad-slot"] {
    background-color: #14181d !important;
  }

  /* ====================================================================
     TradingView market-ticker (cross-origin iframe) — can't recolor its
     contents, so darken the wrapper + dim the iframe to remove the white band.
     ==================================================================== */
  .tradingview-widget-container, .tradingview-widget-container__widget,
  [class*="tradingview"], [id*="tradingview"],
  .mntl-tradingview, .market-ticker, .ticker-tape {
    background-color: #0d1117 !important;
  }
  iframe[src*="tradingview"], iframe[id*="tradingview"],
  iframe[src*="s.tradingview"], iframe[title*="ticker"] {
    background-color: #0d1117 !important;
    filter: invert(1) hue-rotate(180deg) brightness(0.95) !important;
  }

  /* ====================================================================
     Promo / textnote block ("Trade with Capital.com") — heading + bold
     intro render black-on-dark by default.
     ==================================================================== */
  /* live promo class is "mm-ads-textnote" — match by substring + the heading */
  .textnote, .textnote__heading, .textnote__body,
  .textnote strong, .textnote b, .textnote p,
  .textnote__heading *, [class*="textnote"], [class*="textnote"] *,
  [class*="textnote"] .heading, [class*="textnote"] h2,
  [class*="textnote"] h3, [class*="textnote"] strong,
  [class*="textnote"] b, [class*="textnote"] p {
    color: #e6edf3 !important;
  }
  [class*="textnote"] p, [class*="textnote"] .textnote__body { color: #c4cdd6 !important; }

  /* ====================================================================
     Sticky "Top Stories" recirc bar — story pills bleed white. Make the
     sticky surface + its pills opaque dark.
     ==================================================================== */
  .mntl-recirc-list, .recirc-list, .top-stories, .mntl-top-stories,
  .sticky-rail, [class*="recirc"], [class*="top-stories"],
  .mntl-sticky-recirc, .sticky-recirc {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }
  .mntl-recirc-list__item, .recirc-list__item,
  [class*="recirc"] a, [class*="recirc"] li,
  [class*="top-stories"] a, [class*="top-stories"] li {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* ====================================================================
     Buttons / CTAs (refined Investopedia blue)
     ==================================================================== */
  button, .mntl-button, .btn, .button,
  input[type="submit"], input[type="button"] {
    border-color: #2d333b !important;
  }
  .btn--primary, .button--primary, .mntl-button--primary,
  .newsletter__submit, .subscribe-btn {
    background-color: #2563a8 !important;
    color: #ffffff !important;
    border-color: #2563a8 !important;
  }
  .btn--primary:hover, .button--primary:hover { background-color: #2f74c0 !important; }
  /* Newsletter dialog CTA pill (light-blue rgb(197,220,255) by default) */
  .mntl-newsletter-dialog--footer-link, .dialog-link,
  .mntl-newsletter-dialog, .mntl-newsletter-dialog__content,
  .newsletter-signup, .mntl-newsletter {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .mntl-newsletter-dialog--footer-link, .mntl-newsletter-dialog--footer-link .link__wrapper,
  .mntl-newsletter-dialog *, .newsletter-signup * { color: #e6edf3 !important; }
  .mntl-newsletter-dialog--footer-link:hover { background-color: #2d333b !important; }
  /* Newsletter Sign Up modal (a11y dialog). Live markup is .dialog__content /
     .newsletter__form / .newsletter__subscriptions-wrapper — NOT the
     .mntl-newsletter-dialog classes above — so the panel shipped WHITE and its
     (already-light) labels went invisible on it. Darken every surface; the blue
     .dialog__header band and "I'm In!" CTA are brand and stay. */
  .dialog__content, .dialog__body, .dialog__inner,
  .newsletter__form, .js-newsletter-form,
  .newsletter__subscriptions-wrapper, .newsletter__subscriptions {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .newsletter__subscriptions-wrapper { background-color: #181d23 !important; }
  .dialog__content .newsletter__label, .dialog__content .newsletter__description,
  .dialog__content .newsletter__email-address, .dialog__content .dialog__title,
  .newsletter__subscriptions-wrapper, .newsletter__subscriptions-wrapper * {
    color: #c4cdd6 !important;
  }
  .dialog__content .dialog__title, .newsletter__subscriptions-title { color: #e6edf3 !important; }

  /* ====================================================================
     Investopedia Simulator (/simulator) — a SEPARATE Vuetify microsite
     (.v-application.v-theme--light) with its own coherent light+blue+lime
     branded design that the theme does not (and should not) fully repaint.
     Our generic text rules bleed onto two spots and make them light-on-light:
     the FAQ question headings (span.faq-title) and the lime "Get Started"
     button labels. Restore dark text so the microsite stays readable.
     Scope everything to .v-application so the editorial site is untouched.
     ==================================================================== */
  .v-application .faq-title {
    color: #14181d !important;
    -webkit-text-fill-color: #14181d !important;
  }
  .v-application .v-btn.bg-grellow,
  .v-application .v-btn.bg-grellow .v-btn__content,
  .v-application .v-btn.bg-grellow span {
    color: #14181d !important;
    -webkit-text-fill-color: #14181d !important;
  }

  /* ====================================================================
     Borders / dividers / misc
     ==================================================================== */
  * { border-color: #262c33 !important; }
  hr, .divider, .mntl-divider { border-color: #2d333b !important; background-color: #2d333b !important; }
  ::selection { background-color: #2563a8 !important; color: #ffffff !important; }

  /* Semantic finance colors — keep green up / red down readable on dark */
  .is-positive, .positive, .up, .gain, .price-up, [class*="--positive"],
  .text-success, .stock-up { color: #3fb950 !important; }
  .is-negative, .negative, .down, .loss, .price-down, [class*="--negative"],
  .text-danger, .stock-down { color: #f85149 !important; }

  /* Safety net: any element painted pure-white inline */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background:#fff"], [style*="background: #fff"],
  [style*="background-color:#fff"], [style*="background-color: #fff"] {
    background-color: #1c2128 !important;
  }
}
